<?php
declare(strict_types=1);
namespace App\Interface\Http\Taxonomy\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\Taxonomy\DTO\Request\CreateTaxonomySubjectAliasRequestDto;use App\Application\Taxonomy\Service\CreateTaxonomySubjectAliasService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class TaxonomySubjectAliasController { public function __construct(private readonly AuthService $auth,private readonly CreateTaxonomySubjectAliasService $create,private readonly ApiResponseFactory $responses){} public function create(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,CreateTaxonomySubjectAliasRequestDto $input):ResponseInterface{try{$user=$this->auth->currentUser($access);}catch(DomainException|UnavailableUserException){return $this->responses->problem($response,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$request->getAttribute('request_id'));}if(!in_array('ADMIN',$user->roles,true))return $this->responses->problem($response,'FORBIDDEN','Permissao insuficiente.',403,(string)$request->getAttribute('request_id'));try{$alias=$this->create->create($input);}catch(DomainException|\InvalidArgumentException $e){return $this->responses->problem($response,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$request->getAttribute('request_id'),[['field'=>'request','code'=>'INVALID_VALUE','message'=>$e->getMessage()]]);}return $this->responses->success($response,$alias,(string)$request->getAttribute('request_id'),201);} }
